"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。

语义以 ``docs/TASKSCHEMA.md`` §3 - §5、§8 为准：

* 四种日程的主出现日（每日任务锚定在 ``StartBoundary`` 的日期上）；
* 主出现时刻取 ``StartBoundary`` 的时分秒，且必须 ``>= StartBoundary``；
* ``EndBoundary`` 之后的时刻不再触发（重复产生的时刻同样受约束）；
* ``Repetition`` 在主出现 ``T`` 之后产生 ``T + k*Interval``，只保留满足
  ``k*Interval < Duration`` 的那些（``Duration`` 缺省表示不限时长）；
* 任务被禁用时不产生任何时刻，单个触发器被禁用时跳过该触发器。
"""

import calendar
import heapq
from datetime import datetime, timedelta

from .errors import TaskDefError

__all__ = [
    "HORIZON_DAYS",
    "PLAN_HARD_LIMIT",
    "next_runs",
    "plan_window",
    "validate_task",
]

#: 主出现扫描的最大跨度（天）。超出该跨度的任务定义视为不可调度。
HORIZON_DAYS = 800

#: ``plan_window`` 一次最多枚举多少次运行。
PLAN_HARD_LIMIT = 20000

#: 合法的触发器 ``type``
TRIGGER_TYPES = ("time", "daily", "weekly", "monthly", "monthly_dow")

_ZERO = timedelta(0)


# ------------------------------------------------------------------ 日历工具


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周的周一（周按周一起始划分）。"""
    return day - timedelta(days=day.weekday())


def _week_index(day):
    """返回 ``day`` 在本月内的日历周序号（1 起，按日号划分）。

    1-7 日为第 1 周，8-14 日为第 2 周，……，29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month + 6) // 7


def _match_week(day, wanted):
    """``<Week>`` 匹配。

    1..4 表示第 n 周；**5 表示该月的最后一周**（在只有 4 个日历周的月份里
    —— 例如平年 2 月 —— 匹配的是第 4 周）。
    """
    index = _week_index(day)
    last = _weeks_in_month(day)
    for week in wanted:
        if week == 5:
            if index == last:
                return True
        elif index == week:
            return True
    return False


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    kind = trigger.type

    if kind == "daily":
        interval = trigger.days_interval
        if not 1 <= interval <= 365:
            raise TaskDefError("range", "DaysInterval %r out of 1..365" % (interval,))
        # 锚点是 StartBoundary 的日期，而不是「当月的日号」。
        return (day - trigger.start.date()).days % interval == 0

    if kind == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = trigger.weeks_interval
        if not 1 <= interval <= 52:
            raise TaskDefError("range", "WeeksInterval %r out of 1..52" % (interval,))
        if interval == 1:
            return True
        # 从 StartBoundary 所在的周（周一）算起，周序号差必须是 interval 的整数倍。
        weeks = (_week_start(day) - _week_start(trigger.start.date())).days // 7
        return weeks % interval == 0

    if kind == "monthly":
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if kind == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if kind == "time":
        return day == trigger.start.date()

    raise TaskDefError("trigger", "unknown trigger type: %r" % (kind,))


# ------------------------------------------------------------------ 出现时刻


def _scan_floor(trigger, after):
    """日扫描的起始日期：早于它的日号不可能产生 ``> after`` 的运行时刻。"""
    start_day = trigger.start.date()
    rep = trigger.repetition
    if rep is None:
        floor = after.date()
    elif rep.duration is None:
        # 不限时长的重复：任何历史主出现都会一直重复下去。
        return start_day
    elif rep.interval > _ZERO:
        floor = (after - rep.duration).date()
    else:
        floor = after.date()
    return start_day if floor < start_day else floor


def _primary_occurrences(trigger, after, last_day=None):
    """按升序惰性产出主出现时刻（含早于 ``after`` 的，供重复展开使用）。"""
    tod = trigger.start.time()
    day = _scan_floor(trigger, after)
    stop = after.date() + timedelta(days=HORIZON_DAYS)
    if last_day is not None and last_day < stop:
        stop = last_day
    if trigger.end is not None and trigger.end.date() < stop:
        stop = trigger.end.date()
    while day <= stop:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, tod)
            if moment >= trigger.start:
                if trigger.end is not None and moment > trigger.end:
                    return
                yield moment
        day += timedelta(days=1)


def _first_run(trigger, occurrence, after):
    """该主出现产生的、**严格晚于** ``after`` 的第一次运行。

    返回 ``(k, moment)``；若不存在则返回 ``None``。
    """
    rep = trigger.repetition
    if rep is None or rep.interval <= _ZERO:
        return (0, occurrence) if occurrence > after else None

    interval = rep.interval
    if occurrence > after:
        step = 0
    else:
        step = (after - occurrence) // interval + 1
    if rep.duration is not None and step * interval >= rep.duration:
        return None
    return step, occurrence + step * interval


def _runs_for_trigger(trigger, after, count, until=None):
    """单个触发器在 ``after`` 之后（且不超过 ``until``）的运行时刻。

    结果升序、去重，最多 ``count`` 个。
    """
    if count <= 0:
        return []

    rep = trigger.repetition
    repeating = rep is not None and rep.interval > _ZERO
    # EndBoundary 同样约束重复产生的时刻。
    bound = until
    if trigger.end is not None and (bound is None or trigger.end < bound):
        bound = trigger.end
    last_day = bound.date() if bound is not None else None

    occurrences = _primary_occurrences(trigger, after, last_day)
    pending = next(occurrences, None)
    heap = []
    sequence = 0
    runs = []
    seen = set()

    # 「不限时长」的重复里，相位相同（相差 Interval 的整数倍）的主出现会产生
    # 完全被覆盖的运行序列，跳过它们只是性能优化，不影响结果。
    unlimited = repeating and rep.duration is None
    base = None
    phases = set()

    while True:
        # 主出现按时间递增；任何首元素不晚于当前堆顶的主出现都必须先入堆，
        # 这样才能保证产出严格升序。
        while pending is not None and (not heap or pending <= heap[0][0]):
            first = _first_run(trigger, pending, after)
            sequence += 1
            if first is not None:
                if not unlimited:
                    heapq.heappush(heap, (first[1], sequence, first[0]))
                else:
                    if base is None:
                        base = pending
                    phase = (pending - base) % rep.interval
                    if phase not in phases:
                        phases.add(phase)
                        heapq.heappush(heap, (first[1], sequence, first[0]))
            pending = next(occurrences, None)

        if not heap:
            break

        moment, index, step = heapq.heappop(heap)
        if bound is not None and moment > bound:
            break  # 堆里剩下的只会更晚
        if moment > after and moment not in seen:
            seen.add(moment)
            runs.append(moment)
            if len(runs) >= count:
                break
        if repeating:
            next_step = step + 1
            if rep.duration is None or next_step * rep.interval < rep.duration:
                candidate = moment + rep.interval
                if bound is None or candidate <= bound:
                    heapq.heappush(heap, (candidate, index, next_step))

    return runs


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    try:
        count = int(count)
    except (TypeError, ValueError):
        return []
    if count <= 0:
        return []
    if not task.enabled:
        return []

    moments = []
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        moments.extend(_runs_for_trigger(trigger, after, count))

    return sorted(set(moments))[:count]


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if end < start:
        return []
    if not task.enabled:
        return []

    moments = []
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        moments.extend(_runs_for_trigger(trigger, start, PLAN_HARD_LIMIT, until=end))

    return sorted(set(moments))[:PLAN_HARD_LIMIT]


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。

    校验通过的 ``task`` 原样返回。
    """
    triggers = tuple(task.triggers or ())
    if not triggers:
        raise TaskDefError("structure", "task has no triggers")

    for trigger in triggers:
        kind = trigger.type
        if kind not in TRIGGER_TYPES:
            raise TaskDefError("trigger", "unknown trigger type: %r" % (kind,))
        if not isinstance(trigger.start, datetime):
            raise TaskDefError("range", "StartBoundary must be a datetime")
        if trigger.end is not None:
            if not isinstance(trigger.end, datetime):
                raise TaskDefError("range", "EndBoundary must be a datetime")
            if trigger.end < trigger.start:
                raise TaskDefError(
                    "structure",
                    "EndBoundary %s is earlier than StartBoundary %s"
                    % (trigger.end.isoformat(), trigger.start.isoformat()),
                )

        if kind == "daily":
            if not 1 <= trigger.days_interval <= 365:
                raise TaskDefError(
                    "range", "DaysInterval %r out of 1..365" % (trigger.days_interval,)
                )
        elif kind == "weekly":
            if not 1 <= trigger.weeks_interval <= 52:
                raise TaskDefError(
                    "range", "WeeksInterval %r out of 1..52" % (trigger.weeks_interval,)
                )
            _validate_weekdays(trigger.days_of_week)
        elif kind == "monthly":
            if not trigger.days_of_month:
                raise TaskDefError("trigger", "<DaysOfMonth> is empty")
            for value in trigger.days_of_month:
                if not 1 <= value <= 31:
                    raise TaskDefError("range", "Day %r out of 1..31" % (value,))
            _validate_months(trigger.months)
        elif kind == "monthly_dow":
            if not trigger.weeks_of_month:
                raise TaskDefError("trigger", "<Weeks> is empty")
            for value in trigger.weeks_of_month:
                if not 1 <= value <= 5:
                    raise TaskDefError("range", "Week %r out of 1..5" % (value,))
            _validate_weekdays(trigger.days_of_week)
            _validate_months(trigger.months)

        rep = trigger.repetition
        if rep is not None:
            if not isinstance(rep.interval, timedelta) or rep.interval <= _ZERO:
                raise TaskDefError(
                    "range", "repetition <Interval> must be a positive duration"
                )
            if rep.duration is not None and rep.duration <= _ZERO:
                raise TaskDefError(
                    "range", "repetition <Duration> must be a positive duration"
                )

    limit = task.execution_time_limit
    if limit is not None and (not isinstance(limit, timedelta) or limit < _ZERO):
        raise TaskDefError("duration", "invalid <ExecutionTimeLimit>")
    delay = task.random_delay
    if delay is not None and (not isinstance(delay, timedelta) or delay < _ZERO):
        raise TaskDefError("duration", "invalid <RandomDelay>")

    return task


def _validate_weekdays(days_of_week):
    days = tuple(days_of_week or ())
    if not days:
        raise TaskDefError("trigger", "<DaysOfWeek> is empty")
    for value in days:
        if not 0 <= value <= 6:
            raise TaskDefError("trigger", "unknown weekday %r" % (value,))
    if len(set(days)) != len(days):
        raise TaskDefError("trigger", "duplicate weekday in <DaysOfWeek>")


def _validate_months(months):
    values = tuple(months or ())
    if not values:
        raise TaskDefError("trigger", "<Months> is empty")
    for value in values:
        if not 1 <= value <= 12:
            raise TaskDefError("range", "month %r out of 1..12" % (value,))
    if len(set(values)) != len(values):
        raise TaskDefError("trigger", "duplicate month in <Months>")
